/**
 * Search helper function supporting partial matching, alternate spellings,
 * Kannada names, and district/taluk text matching.
 */
export function searchLocations(query, maxResults = 15) {
  if (!query || typeof query !== 'string' || !query.trim()) {
    return karnatakaLocations.slice(0, maxResults);
  }

  const q = query.trim().toLowerCase();

  const matches = karnatakaLocations.map(loc => {
    let score = 0;

    const name = loc.name.toLowerCase();
    const nameKn = (loc.nameKn || '').toLowerCase();
    const altName = (loc.altName || '').toLowerCase();
    const district = loc.district.toLowerCase();
    const taluk = (loc.taluk || '').toLowerCase();

    // Exact matches
    if (name === q || altName.split(',').map(s => s.trim()).includes(q)) {
      score += 100;
    }
    // Prefix matches
    else if (name.startsWith(q)) {
      score += 80;
    }
    else if (altName.split(',').some(s => s.trim().startsWith(q))) {
      score += 70;
    }
    // Substring matches
    else if (name.includes(q)) {
      score += 50;
    }
    else if (altName.includes(q)) {
      score += 40;
    }
    else if (nameKn.includes(q)) {
      score += 40;
    }
    // Taluk or District matches
    else if (taluk.startsWith(q)) {
      score += 30;
    }
    else if (district.startsWith(q)) {
      score += 20;
    }
    else if (district.includes(q) || taluk.includes(q)) {
      score += 10;
    }

    if (score > 0) {
      if (loc.type === 'CITY') score += 5;
      if (loc.type === 'TALUK_HEADQUARTER') score += 2;
    }

    return { loc, score };
  });

  return matches
    .filter(m => m.score > 0)
    .sort((a, b) => b.score - a.score)
    .map(m => m.loc)
    .slice(0, maxResults);
}
